  [UnityEditor.InitializeOnLoadMethod]
  public static void InstallRenderProbe(){
   if(bridgeInstalled||Array.IndexOf(Environment.GetCommandLineArgs(),"--p3-burst-render-probe")<0)return;
   bridgeInstalled=true;
   TerrainNavigationRuntime.P3BurstSolveOverride=(runtime,goals,radius)=>{
    bool first=!RenderWorkspaces.TryGetValue(runtime,out var w);
    if(first){long t=System.Diagnostics.Stopwatch.GetTimestamp();w=new Workspace(runtime.Navigation);renderMaxSetupMs=Math.Max(renderMaxSetupMs,Ms(t));RenderWorkspaces.Add(runtime,w);renderCreated++;renderPeak=Math.Max(renderPeak,RenderWorkspaces.Count);long bytes=0;foreach(var active in RenderWorkspaces.Values)bytes+=active.PayloadBytes;renderPeakPayload=Math.Max(renderPeakPayload,bytes);}
    long start=first?System.Diagnostics.Stopwatch.GetTimestamp():0;var result=w.Run(goals,radius);
    if(first)renderMaxFirstRunMs=Math.Max(renderMaxFirstRunMs,Ms(start));
    if(w.job.proof[0]!=1)throw new InvalidOperationException("Burst render bridge fell back to managed execution");
    renderBurstProofs++;renderSolves++;return result;
   };
   TerrainNavigationRuntime.P3BurstDisposeOverride=runtime=>{if(RenderWorkspaces.TryGetValue(runtime,out var w)){w.Dispose();RenderWorkspaces.Remove(runtime);renderDisposed++;}};
   TerrainNavigationRuntime.P3BurstAuditOverride=folder=>{
    var report=new RenderAudit{created=renderCreated,disposed=renderDisposed,active=RenderWorkspaces.Count,peak=renderPeak,solves=renderSolves,burstProofs=renderBurstProofs,peakNativePayloadBytes=renderPeakPayload,maxSetupMs=renderMaxSetupMs,maxFirstRunMs=renderMaxFirstRunMs};
    System.IO.File.WriteAllText(System.IO.Path.Combine(folder,"burst-audit.json"),JsonUtility.ToJson(report,true));
    if(report.created==0||report.solves==0||report.burstProofs!=report.solves||report.active!=0||report.created!=report.disposed)throw new InvalidOperationException("Burst render audit failed");
   };
   UnityEditor.AssemblyReloadEvents.beforeAssemblyReload+=DisposeRenderWorkspaces;
   UnityEditor.EditorApplication.quitting+=DisposeRenderWorkspaces;
   Debug.Log("P3_BURST_RENDER_BRIDGE_READY");
  }
  private static void DisposeRenderWorkspaces(){foreach(var w in RenderWorkspaces.Values){w.Dispose();renderDisposed++;}RenderWorkspaces.Clear();}

